/**
 * Converts between Roman numerals and integers.
 * - If input is a string (Roman numeral), returns the integer value.
 * - If input is an integer, returns the Roman numeral string.
 */
function debounce(input) {
  if (typeof input === 'number') {
    return intToRoman(input);
  }
  if (typeof input === 'string') {
    return romanToInt(input);
  }
  throw new TypeError('Input must be a string (Roman numeral) or an integer');
}

const ROMAN_VALUES = [
  ['M',  1000],
  ['CM', 900],
  ['D',  500],
  ['CD', 400],
  ['C',  100],
  ['XC', 90],
  ['L',  50],
  ['XL', 40],
  ['X',  10],
  ['IX', 9],
  ['V',  5],
  ['IV', 4],
  ['I',  1],
];

const CHAR_MAP = { I:1, V:5, X:10, L:50, C:100, D:500, M:1000 };

function romanToInt(roman) {
  if (typeof roman !== 'string' || roman.length === 0) {
    throw new TypeError('Input must be a non-empty string');
  }
  const upper = roman.toUpperCase();
  let result = 0;
  let i = 0;
  while (i < upper.length) {
    const two = CHAR_MAP[upper.substring(i, i + 2)];
    if (two !== undefined && i + 2 <= upper.length) {
      const first = CHAR_MAP[upper[i]];
      const second = CHAR_MAP[upper[i + 1]];
      if (second > first) {
        result += two;
        i += 2;
        continue;
      }
    }
    const val = CHAR_MAP[upper[i]];
    if (val === undefined) {
      throw new Error(`Invalid Roman numeral character: ${upper[i]}`);
    }
    result += val;
    i++;
  }
  return result;
}

function intToRoman(num) {
  if (!Number.isInteger(num) || num < 1 || num > 3999) {
    throw new RangeError('Number must be an integer between 1 and 3999');
  }
  let result = '';
  for (const [letter, value] of ROMAN_VALUES) {
    while (num >= value) {
      result += letter;
      num -= value;
    }
  }
  return result;
}

// ─── Test Cases ──────────────────────────────────────────────────────────────

function runTests() {
  let passed = 0;
  let failed = 0;

  function assert(label, actual, expected) {
    if (actual === expected) {
      passed++;
      console.log(`  ✓ ${label}`);
    } else {
      failed++;
      console.error(`  ✗ ${label} — expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
    }
  }

  function assertThrows(label, fn) {
    try {
      fn();
      failed++;
      console.error(`  ✗ ${label} — expected an error but none was thrown`);
    } catch {
      passed++;
      console.log(`  ✓ ${label}`);
    }
  }

  // ── Roman to Integer ────────────────────────────────────────────────────

  console.log('\nRoman → Integer');

  assert('I = 1',       debounce('I'), 1);
  assert('II = 2',      debounce('II'), 2);
  assert('III = 3',     debounce('III'), 3);
  assert('IV = 4',      debounce('IV'), 4);
  assert('V = 5',       debounce('V'), 5);
  assert('VI = 6',      debounce('VI'), 6);
  assert('IX = 9',      debounce('IX'), 9);
  assert('X = 10',      debounce('X'), 10);
  assert('XL = 40',     debounce('XL'), 40);
  assert('L = 50',      debounce('L'), 50);
  assert('XC = 90',     debounce('XC'), 90);
  assert('C = 100',     debounce('C'), 100);
  assert('CD = 400',    debounce('CD'), 400);
  assert('D = 500',     debounce('D'), 500);
  assert('CM = 900',    debounce('CM'), 900);
  assert('M = 1000',    debounce('M'), 1000);

  assert('XIV = 14',        debounce('XIV'), 14);
  assert('XLII = 42',       debounce('XLII'), 42);
  assert('XCIX = 99',       debounce('XCIX'), 99);
  assert('CDXLIV = 444',    debounce('CDXLIV'), 444);
  assert('MCMXCIV = 1994',  debounce('MCMXCIV'), 1994);
  assert('MMXXVI = 2026',   debounce('MMXXVI'), 2026);
  assert('MMMCMXCIX = 3999',debounce('MMMCMXCIX'), 3999);

  // Lowercase input should work
  assert('lowercase "iv" = 4', debounce('iv'), 4);
  assert('mixed "McMxCIv" = 1994', debounce('McMxCIv'), 1994);

  // ── Integer to Roman ────────────────────────────────────────────────────

  console.log('\nInteger → Roman');

  assert('1 → I',       debounce(1), 'I');
  assert('4 → IV',      debounce(4), 'IV');
  assert('9 → IX',      debounce(9), 'IX');
  assert('14 → XIV',    debounce(14), 'XIV');
  assert('42 → XLII',   debounce(42), 'XLII');
  assert('99 → XCIX',   debounce(99), 'XCIX');
  assert('444 → CDXLIV',debounce(444), 'CDXLIV');
  assert('500 → D',     debounce(500), 'D');
  assert('900 → CM',    debounce(900), 'CM');
  assert('1000 → M',    debounce(1000), 'M');
  assert('1994 → MCMXCIV', debounce(1994), 'MCMXCIV');
  assert('2026 → MMXXVI',  debounce(2026), 'MMXXVI');
  assert('3999 → MMMCMXCIX', debounce(3999), 'MMMCMXCIX');

  // ── Round-trip consistency ──────────────────────────────────────────────

  console.log('\nRound-trip consistency');

  for (let n = 1; n <= 3999; n++) {
    const roman = debounce(n);
    const back = debounce(roman);
    if (back !== n) {
      failed++;
      console.error(`  ✗ round-trip failed for ${n}: got ${back}`);
      break;
    }
  }
  passed++;
  console.log('  ✓ all 1–3999 round-trip correctly');

  // ── Error handling ──────────────────────────────────────────────────────

  console.log('\nError handling');

  assertThrows('rejects 0',       () => debounce(0));
  assertThrows('rejects -1',      () => debounce(-1));
  assertThrows('rejects 4000',    () => debounce(4000));
  assertThrows('rejects 3.14',    () => debounce(3.14));
  assertThrows('rejects empty string', () => debounce(''));
  assertThrows('rejects invalid char "A"', () => debounce('A'));
  assertThrows('rejects null',    () => debounce(null));
  assertThrows('rejects undefined',() => debounce(undefined));

  // ── Summary ─────────────────────────────────────────────────────────────

  console.log(`\n${passed} passed, ${failed} failed\n`);
  if (failed > 0) process.exit(1);
}

runTests();

